import os
import json
import base64
from typing import Any, Dict, List, Union

import boto3


def detect_labels_or_objects(image_input: Union[str, bytes, bytearray]) -> Dict[str, Any]:
    """
    Detect labels/objects in a static image using Amazon Rekognition.

    Args:
        image_input: Either a file path (str) to an image or raw image bytes.

    Returns:
        A dictionary containing detected labels and image metadata.
    """
    if isinstance(image_input, str):
        with open(image_input, "rb") as f:
            image_bytes = f.read()
    elif isinstance(image_input, (bytes, bytearray)):
        image_bytes = bytes(image_input)
    else:
        raise TypeError("image_input must be a file path string or image bytes")

    client = boto3.client("rekognition")

    response = client.detect_labels(
        Image={"Bytes": image_bytes},
        MaxLabels=20,
        MinConfidence=50.0,
    )

    labels: List[Dict[str, Any]] = []
    for label in response.get("Labels", []):
        entry: Dict[str, Any] = {
            "name": label.get("Name"),
            "confidence": label.get("Confidence"),
            "instances": [],
            "parents": [p.get("Name") for p in label.get("Parents", []) if p.get("Name")],
        }

        for inst in label.get("Instances", []):
            bbox = inst.get("BoundingBox", {})
            entry["instances"].append(
                {
                    "confidence": inst.get("Confidence"),
                    "bounding_box": {
                        "left": bbox.get("Left"),
                        "top": bbox.get("Top"),
                        "width": bbox.get("Width"),
                        "height": bbox.get("Height"),
                    },
                }
            )

        labels.append(entry)

    return {
        "provider": "amazon_rekognition",
        "labels": labels,
        "orientation_correction": response.get("OrientationCorrection"),
        "response_metadata": {
            "request_id": response.get("ResponseMetadata", {}).get("RequestId"),
            "http_status_code": response.get("ResponseMetadata", {}).get("HTTPStatusCode"),
        },
    }


def detect_text_in_image(image_input: Union[str, bytes, bytearray]) -> Dict[str, Any]:
    """
    Detect text in a static image using Amazon Rekognition.

    Args:
        image_input: Either a file path (str) to an image or raw image bytes.

    Returns:
        A dictionary containing detected text lines/words.
    """
    if isinstance(image_input, str):
        with open(image_input, "rb") as f:
            image_bytes = f.read()
    elif isinstance(image_input, (bytes, bytearray)):
        image_bytes = bytes(image_input)
    else:
        raise TypeError("image_input must be a file path string or image bytes")

    client = boto3.client("rekognition")

    response = client.detect_text(Image={"Bytes": image_bytes})

    text_detections: List[Dict[str, Any]] = []
    for item in response.get("TextDetections", []):
        geometry = item.get("Geometry", {})
        bbox = geometry.get("BoundingBox", {})
        polygon = geometry.get("Polygon", [])

        text_detections.append(
            {
                "detected_text": item.get("DetectedText"),
                "confidence": item.get("Confidence"),
                "type": item.get("Type"),
                "id": item.get("Id"),
                "parent_id": item.get("ParentId"),
                "bounding_box": {
                    "left": bbox.get("Left"),
                    "top": bbox.get("Top"),
                    "width": bbox.get("Width"),
                    "height": bbox.get("Height"),
                },
                "polygon": [
                    {"x": point.get("X"), "y": point.get("Y")}
                    for point in polygon
                ],
            }
        )

    return {
        "provider": "amazon_rekognition",
        "text_detections": text_detections,
        "orientation_correction": response.get("TextModelVersion"),
        "response_metadata": {
            "request_id": response.get("ResponseMetadata", {}).get("RequestId"),
            "http_status_code": response.get("ResponseMetadata", {}).get("HTTPStatusCode"),
        },
    }


def analyze_image(image_input: Union[str, bytes, bytearray], mode: str = "labels") -> Dict[str, Any]:
    """
    Analyze a static image for either labels or text.
    """
    mode_normalized = mode.lower().strip()
    if mode_normalized in {"labels", "objects"}:
        return detect_labels_or_objects(image_input)
    if mode_normalized in {"text", "ocr"}:
        return detect_text_in_image(image_input)
    raise ValueError("mode must be one of: labels, objects, text, ocr")
